css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #0B7A45; text-decoration: none; }
.dcx a:hover{ color: #0A6A3C; }
.dcx :focus-visible{ outline: 2px solid #6FE3A6; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-herogrid],.dcx [data-flowgrid],.dcx [data-darkgrid],.dcx [data-ctagrid],.dcx [data-resgrid]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-rail]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-rail] > div{ border-left: 0 !important; border-top: 1px solid rgba(8,18,13,.08) !important; }
.dcx [data-h1]{ font-size: 40px !important; }
.dcx [data-h2]{ font-size: 32px !important; }
.dcx [data-hand]{ display: none !important; }
.dcx [data-interior]{ height: 240px !important; }
}
@media (max-width: 640px){.dcx [data-rail]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-stats]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 33px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
